{
{# Last updated by Dylan 2026-10-09, added additional type mappings
#- Oct 2026 by Diego Pino (WIP).
So far only Series. To be enriched with more fields as we start seeingcleaned up CSVs -#}
{% set type_mapping = {
  "Shows" : "Series",
  "Subseries" : "Subseries",
  "Season" : "Season",
  } %}
  "label": {{ data.label|json_encode|raw }},
  "type": {{ type_mapping[data.type]|default("Collection")|json_encode|raw }},
  {% set local_identifiers = [{"source":"Cortex Record ID","value":data.recordid|default('Undefined')}] %}
  {% for local_id in data.nypr_external_identifier_type_and_identifier|default([]) %}
     {% set local_id_split = local_id|split('(') %}
     {% set local_identifiers = local_identifiers|merge([{"source": local_id_split[0]|default('Undefined'), "value": local_id_split[1]|default('none')|trim(')')}]) %}
  {% endfor %}
  "local_identifiers": {{ local_identifiers|json_encode|raw }},
  "source_system": {{ data.source_system|default("Cortext")|json_encode|raw }},
  "minimum_viable_metadata_present": "Yes",
  "as:generator": {
        "type": "Create",
        "actor": {
            "url": {{ setURL|json_encode|raw }},
            "name": "ami",
            "type": "Service"
        },
        "endTime": "{{"now"|date("c")}}",
        "summary": "Generator",
        "@context": "https:\/\/www.w3.org\/ns\/activitystreams"
     }
}
